function updateClock() {
  var now = new Date();
  var time = now.toLocaleTimeString();
  document.getElementById('working-clock').textContent = time;
}

// Wait 1 second before starting the clock
setTimeout(function () {
  // Update the clock every second
  var clockInterval = setInterval(updateClock, 1000);

  // Stop updating after 10 seconds
  setTimeout(function () {
    clearInterval(clockInterval);
  }, 10000);
}, 1000);

// Show the time immediately
updateClock();

